var fs = require('fs'),
    Path = require('path'),
    lodash = require('lodash'),
    Utils = require('./utils'),
    CtrlFactory = require('./ControllerFactory')

module.exports = (function () {
    var Controllers = function (options) {
        this.options = Utils._.extend({
            defineController: {}
        }, options ||{})
    }

    Controllers.prototype.defineController = function (controllerName, options) {
        options = options || {}
        var me = this
            , globalOptions = me.options

        if (globalOptions.defineController) {
            options = Utils._.extend(globalOptions.defineController, options)
            Utils._(['classMethods']).each(function (key) {
                if (globalOptions.defineController[key]) {
                    options[key] = options[key] || {}
                    Utils._.extend(options[key], globalOptions.defineController[key])
                }
            })
        }
        var factory = new CtrlFactory(controllerName, options)
        return factory
    }

    Controllers.prototype.importController = function (path, file) {
        // is it a relative path?
        if (Path.normalize(path).indexOf(path.sep) !== 0) {
            // make path relative to the caller
            var callerFilename = path + "/index.js"
                , callerPath = Path.dirname(callerFilename)
            path = Path.resolve(callerPath, path + "/" + file)
        }
        var importCache = {};
        if (!importCache[path]) {
            var defineCall = require(path)
            importCache[path] = defineCall(this)
        }
        return importCache[path]
    }

    return Controllers
})()

